#!/usr/bin/env python3
"""
Diagnostics scorer for factory line QA.
Reads input.json, writes output.json deterministically.
"""

import json
import sys
from collections import defaultdict

def main():
    try:
        with open('/app/data/input.json', 'r') as f:
            data = json.load(f)
    except Exception:
        sys.exit(1)

    training_samples = data['training_samples']
    test_samples = data['test_samples']
    model_config = data['model_config']

    state_categories = model_config['state_categories']
    feature_weights = model_config['feature_weights']
    sensor_priority = model_config['sensor_priority']

    primary_sensors = ['motor_temperature_c', 'vibration_amplitude_mm', 'current_consumption_a', 'position_error_mm']
    all_sensors = list(feature_weights.keys())
    non_primary_sensors = [s for s in all_sensors if s not in primary_sensors]

    states = sorted(state_categories.keys())
    range_keys = ['temperature_range', 'vibration_range', 'current_range', 'position_error_range']
    category_weights = {
        'temperature_range': 0.4,
        'vibration_range': 0.3,
        'current_range': 0.2,
        'position_error_range': 0.1
    }

    all_samples = training_samples + test_samples
    sensor_stats = {}
    for s in non_primary_sensors:
        values = [sample[s] for sample in all_samples]
        sensor_stats[s] = (min(values), max(values))

    hours_values = [sample['operational_hours'] for sample in all_samples]
    hours_min = min(hours_values)
    hours_max = max(hours_values)

    normal_ranges = {rk: state_categories['normal'][rk] for rk in range_keys}
    critical_ranges = {rk: state_categories['critical'][rk] for rk in range_keys}

    denom_match = {rk: critical_ranges[rk][1] - normal_ranges[rk][1] for rk in range_keys}
    denom_anomaly = {rk: critical_ranges[rk][1] - normal_ranges[rk][0] for rk in range_keys}

    def compute_match(value, lo, hi, denom):
        if lo <= value <= hi:
            return 1.0
        distance = lo - value if value < lo else value - hi
        match = 1.0 - distance / denom
        return max(0.0, min(1.0, match))

    def compute_anomaly_severity(value, lo, hi, denom):
        if lo <= value <= hi:
            return None
        distance = lo - value if value < lo else value - hi
        return distance / denom

    predictions = []

    for sample in all_samples:
        sample_id = sample['sample_id']
        sample_data = dict(sample)
        primary_values = {ps: sample_data[ps] for ps in primary_sensors}

        state_scores = {}
        for state_name in states:
            state_data = state_categories[state_name]
            scores = []
            for rk, ps in zip(range_keys, primary_sensors):
                lo, hi = state_data[rk]
                match = compute_match(primary_values[ps], lo, hi, denom_match[rk])
                cat_score = match * category_weights[rk]
                scores.append((cat_score, ps))
            state_scores[state_name] = scores

        best_per_state = {s: max(sc[0] for sc in state_scores[s]) for s in states}
        state_match_score = max(best_per_state.values())

        predicted_state = None
        for state_name in states:
            if abs(best_per_state[state_name] - state_match_score) < 1e-9:
                predicted_state = state_name
                break

        all_cat_scores = []
        for state_name in states:
            for score, _ in state_scores[state_name]:
                all_cat_scores.append(score)
        all_cat_scores.sort(reverse=True)
        best = all_cat_scores[0]
        second = all_cat_scores[1]
        confidence_score = min(1.0, 0.5 + 2.0 * (best - second))
        confidence_score = round(confidence_score, 4)
        state_match_score = round(state_match_score, 4)

        anomaly_indicators = []
        for rk, ps in zip(range_keys, primary_sensors):
            lo, hi = normal_ranges[rk]
            severity = compute_anomaly_severity(primary_values[ps], lo, hi, denom_anomaly[rk])
            if severity is not None and severity > 0.0:
                anomaly_indicators.append({'sensor': ps, 'severity': round(severity, 4)})

        priority_map = {s: i for i, s in enumerate(sensor_priority)}
        for s in primary_sensors:
            if s not in priority_map:
                priority_map[s] = len(sensor_priority)
        anomaly_indicators.sort(key=lambda x: (priority_map[x['sensor']], -x['severity'], x['sensor']))

        feature_contributions = {}
        for s in all_sensors:
            val = sample_data[s]
            if s in primary_sensors:
                rk_map = {'motor_temperature_c': 'temperature_range',
                          'vibration_amplitude_mm': 'vibration_range',
                          'current_consumption_a': 'current_range',
                          'position_error_mm': 'position_error_range'}
                rk = rk_map[s]
                norm_lo, norm_hi = normal_ranges[rk]
                crit_lo, crit_hi = critical_ranges[rk]
                norm_span = crit_hi - norm_lo
                if norm_span == 0:
                    feat_contrib = 0.0 if val == norm_lo else 1.0 if val == crit_hi else 0.5
                else:
                    feat_contrib = (val - norm_lo) / norm_span
            else:
                min_val, max_val = sensor_stats[s]
                span = max_val - min_val
                if span == 0:
                    feat_contrib = 0.0
                else:
                    feat_contrib = (val - min_val) / span

            if s in ['motor_temperature_c', 'vibration_amplitude_mm', 'current_consumption_a']:
                if hours_max == hours_min:
                    hours_norm = 0.0
                else:
                    hours_norm = (sample_data['operational_hours'] - hours_min) / (hours_max - hours_min)
                    hours_norm = max(0.0, min(1.0, hours_norm))
                wear_factor = 1.0 + 0.3 * hours_norm
                feat_contrib *= wear_factor

            feat_contrib = max(0.0, min(1.0, feat_contrib))
            feature_contributions[s] = round(feat_contrib, 4)

        num_anomalies = len(anomaly_indicators)
        if num_anomalies >= 3 and predicted_state == 'normal':
            predicted_state = 'degraded'

        predictions.append({
            'sample_id': sample_id,
            'predicted_state': predicted_state,
            'confidence_score': confidence_score,
            'state_match_score': state_match_score,
            'feature_contributions': feature_contributions,
            'anomaly_indicators': anomaly_indicators
        })

    predictions.sort(key=lambda x: x['sample_id'])

    confusion = {s: {t: 0 for t in states} for s in states}
    train_preds = {p['sample_id']: p for p in predictions if p['sample_id'].startswith('train')}

    for ts in training_samples:
        sid = ts['sample_id']
        actual = ts['system_state']
        pred = train_preds[sid]['predicted_state']
        confusion[actual][pred] += 1

    total = sum(sum(row.values()) for row in confusion.values())
    correct = sum(confusion[s][s] for s in states)
    accuracy = correct / total if total > 0 else 0.0

    metrics = {}
    for s in states:
        tp = confusion[s][s]
        fp = sum(confusion[a][s] for a in states if a != s)
        precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
        fn = sum(confusion[s][p] for p in states if p != s)
        recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
        f1 = 2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0
        metrics[s] = {'precision': round(precision, 4), 'recall': round(recall, 4), 'f1_score': round(f1, 4)}

    avg_precision = sum(metrics[s]['precision'] for s in states) / len(states)
    avg_recall = sum(metrics[s]['recall'] for s in states) / len(states)
    avg_f1 = sum(metrics[s]['f1_score'] for s in states) / len(states)

    model_performance = {
        'accuracy': round(accuracy, 4),
        'confusion_matrix': confusion,
        'precision': round(avg_precision, 4),
        'recall': round(avg_recall, 4),
        'f1_score': round(avg_f1, 4)
    }

    all_contributions = defaultdict(list)
    for p in predictions:
        for sensor, contrib in p['feature_contributions'].items():
            all_contributions[sensor].append(abs(contrib))

    importance_list = []
    for sensor in all_sensors:
        mean_contrib = sum(all_contributions[sensor]) / len(all_contributions[sensor])
        importance = mean_contrib * feature_weights[sensor]
        importance = max(0.0, min(1.0, importance))
        importance_list.append({'feature': sensor, 'importance': round(importance, 4)})

    importance_list.sort(key=lambda x: (-x['importance'], x['feature']))

    output = {
        'predictions': predictions,
        'model_performance': model_performance,
        'feature_importance': importance_list
    }

    json_str = json.dumps(output, sort_keys=True, separators=(',', ':'))
    with open('/app/data/output.json', 'w') as f:
        f.write(json_str + '\n')

if __name__ == '__main__':
    main()
